        uint256 finalBalance = vault.getTotalBalance();
        assertEq(finalBalance, 2 ether, "Balance incorrectly increased after failed transfer");

        // Verify target contract didn't receive the ETH
        assertEq(address(rejectETHContract).balance, 0 ether, "Target contract should not have received ETH");
    }
}

